// ===== AYARLAR =====
const KOMBINASYON = 3;     // her çalıştırmada kaç sektör/şehir araması yapılsın
const FIRMA_SAYISI = 20;   // her aramada kaç firma istensin
const SEHIRLER = [ { ad: "Kocaeli", base: 0 }, { ad: "İstanbul", base: 100 } ];   // Kocaeli önce
const SEKTORLER = ["yazılım geliştirme","web geliştirme","mobil uygulama geliştirme","e-ticaret teknolojileri","oyun geliştirme",
  "yapay zeka ve veri bilimi","fintech","SaaS ve platform geliştirme","otomasyon ve gömülü sistemler","siber güvenlik","danışmanlık ve bilgi teknolojileri"];
// ===================
const pick = a => a[Math.floor(Math.random() * a.length)];
const out = [];
for (let i = 0; i < KOMBINASYON; i++) {
  const s = SEHIRLER[i % SEHIRLER.length], sek = pick(SEKTORLER);
  out.push({ json: { region: s.ad, base: s.base, sektor: sek, prompt:
`Türkiye'de ${s.ad} merkezli veya ${s.ad}'da ofisi olan, ${sek} alanında faaliyet gösteren ${FIRMA_SAYISI} GERÇEK şirket listele. Bilgisayar mühendisi bir aday başvuru yapacak.
Her şirket için: resmi web sitesi alan adı (website) ve insan kaynakları/kariyer için en olası e-posta adresi (email). E-posta mutlaka şirketin KENDİ alan adında olsun ve ik@, kariyer@, hr@, jobs@ ya da info@ kalıplarından biri olsun. Emin olmadığın şirketi listeye alma.
SADECE JSON döndür: {"companies":[{"firma":"","website":"","email":"","sektor":""}]}` } });
}
return out;

// ===== AYARLAR =====
const ORTAK = ["gmail.com","hotmail.com","outlook.com","yahoo.com","yandex.com","icloud.com"];
// ===================
const queue = $('Read Queue').all().map(i => i.json);
const knownMail = new Set(queue.map(r => String(r.Email || '').toLowerCase().trim()).filter(Boolean));
const knownDom = new Set([...knownMail].map(e => e.split('@')[1]));
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9ığüşöç]/g, '');
const knownCo = new Set(queue.map(r => norm(r.Company)).filter(Boolean));
const src = $('Build prompts').all();
const out = [];
$input.all().forEach((item, idx) => {
  const meta = src[item.pairedItem?.item ?? idx]?.json || {};
  let data;
  try {
    const txt = item.json.choices[0].message.content || '';
    data = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
  } catch (e) { return; }
  (data.companies || []).forEach((c, n) => {
    const email = String(c.email || '').toLowerCase().trim();
    if (!/^[a-z0-9._%+\-]+@[a-z0-9\-]+(\.[a-z0-9\-]+)+$/.test(email)) return;
    const dom = email.split('@')[1];
    if (ORTAK.includes(dom) || knownMail.has(email) || knownDom.has(dom) || knownCo.has(norm(c.firma))) return;
    knownMail.add(email); knownDom.add(dom); knownCo.add(norm(c.firma));
    out.push({ json: { Domain: dom, Company: String(c.firma || '').trim(), Email: email, Website: c.website || '', Sector: c.sektor || meta.sektor || '',
      Region: meta.region || '', Rank: Number(meta.base || 0) + n + 1, Type: 'tahmin', Status: 'approved', SentAt: '' } });
  });
});
return out;

// MX kaydı olan alan adlarını geçir; Domain alanını kaldır
const parsed = $('Parse companies').all();
const out = [];
$input.all().forEach((item, idx) => {
  const src = parsed[item.pairedItem?.item ?? idx]?.json;
  if (!src) return;
  const j = item.json || {};
  const ok = j.Status === 0 && Array.isArray(j.Answer) && j.Answer.some(a => a.type === 15);
  if (!ok) return;
  const { Domain, ...rest } = src;
  out.push({ json: rest });
});
return out;

// ===== SETTINGS =====
const DAILY_CAP = 5;                 // max emails per day (start low, raise slowly)
const PROFILE = {
  name: "YOUR NAME",
  phone: "+90 5XX XXX XX XX",
  email: "you@example.com",
  linkedin: "linkedin.com/in/your-profile",
  github: "github.com/your-username"
};
const SUBJECT = "Job Application – " + PROFILE.name;
// Clean company names: "Acme (Plant 2)" -> "Acme"
const clean = (c) => String(c || '').replace(/\s*\([^)]*\)\s*/g, ' ').replace(/\s+/g, ' ').trim();
const BODY = (company) => {
  const co = clean(company);
  return `Dear ${co ? co + ' Team' : 'Hiring Team'},

I am a Computer Engineering graduate with hands-on experience in web, mobile, game development, AI/automation and e-commerce.

I am looking for an opportunity where I can contribute and keep growing. My résumé is attached.

Best regards,
${PROFILE.name}
Phone: ${PROFILE.phone}
Email: ${PROFILE.email}
LinkedIn: ${PROFILE.linkedin}
GitHub: ${PROFILE.github}`;
};
// ====================

const rows = $input.all().map(i => i.json).filter(r => r && r.Email);

// Bounce-rate guard: stop if too many sent mails bounced
const nSent = rows.filter(r => r.Status === 'sent').length;
const nBounced = rows.filter(r => r.Status === 'bounced').length;
if (nSent + nBounced >= 6 && nBounced / (nSent + nBounced) > 0.3) {
  throw new Error('Bounce rate too high (' + nBounced + '/' + (nSent + nBounced) + '). Review the list.');
}

// Daily cap (Europe/Istanbul time)
const today = $now.setZone('Europe/Istanbul').toFormat('yyyy-MM-dd');
const sentToday = rows.filter(r => r.Status === 'sent' && String(r.SentAt || '').startsWith(today)).length;
const left = DAILY_CAP - sentToday;
if (left <= 0) return [];

return rows
  .filter(r => r.Status === 'approved')
  .sort((a, b) => Number(a.Rank) - Number(b.Rank))
  .slice(0, left)
  .map(r => ({ json: { Email: r.Email, Company: r.Company, subject: SUBJECT, body: BODY(r.Company) } }));
